"""arc2 content: spreadsheet pages, batch 1 (the 18 templates that already existed in the app)."""
import json, sys
from pathlib import Path
OUT = Path('/home/claude/FalePDF/network/tools/vorlagen/tabellen')
OUT.mkdir(parents=True, exist_ok=True)
CATS = {}


def T(id, cat, name, short, desc, intro, uses, cols, tips, faq, related, en, slug=None, search=''):
    d = {'id': id, 'slug': slug or id, 'cat': cat, 'name': name, 'short': short, 'desc': desc, 'search': search, 'intro': intro, 'uses': uses,
         'cols': [list(c) for c in cols], 'tips': tips, 'faq': [{'q': q, 'a': a} for q, a in faq], 'related': related, 'en': en}
    for k, v in (('desc', desc), ('en.desc', en['desc'])):
        if not 110 <= len(v) <= 180:
            print(f'{id}: {k} length {len(v)}', file=sys.stderr)
    (OUT / f'{id}.json').write_text(json.dumps(d, ensure_ascii=False, indent=1) + '\n', encoding='utf-8')


def E(slug, name, short, desc, intro, inside, uses):
    return {'slug': slug, 'name': name, 'short': short, 'desc': desc, 'intro': intro, 'inside': inside, 'uses': uses}


